OCR_VERSION = "ocr-4"   # bump when the OCR code changes, so cached OCR is redone


# --- match_albums.py:6575
# Pictures saved from shops and databases, not scanned from your copy: Amazon product
# images ("71-Q6hBQwTL._UF1000,1000_QL80_.jpg", "._AC_SL1500_"), Discogs release images
# ("R-4847696-1388801849-4582.jpg"). Their barcode is some other pressing's (Samael -
# Ceremony Of Opposites: the 2021 MDD reissue's, in a folder ripped in 2005).
_WEB_IMAGE = re.compile(r"\._(?:[A-Z]{2}\d|[A-Z]{2}_)|^R-\d{3,}-\d{9,}(?:-\d+)?$", re.I)


# --- match_albums.py:6578
def web_image(path):
    return bool(_WEB_IMAGE.search(Path(path).stem))


# --- match_albums.py:6635
_EDITION_YEAR = re.compile(r"(?<![\d.])(?:19[5-9]\d|20\d\d)(?![\d.])")


# --- match_albums.py:6637
# EVI-11: an image size in a folder's name ("Covers 2000x2000", "2048px", "600 dpi"): no year
_IMAGE_SIZE = re.compile(r"\d+\s*[x\u00d7]\s*\d+|\d+\s*(?:px|dpi|ppi)\b", re.I)


# --- match_albums.py:6638
_EDITION_WORD = re.compile(r"\b(?:re-?issue|edition|re-?master(?:ed)?|re-?press(?:ing)?|pressing|original|first press)\b",
                           re.I)


# --- match_albums.py:6641
# a catalogue number written in a folder's name, outside brackets too ("scans, A 421 (2004)")
_FOLDER_CODE = re.compile(r"(?<![A-Za-z0-9])([A-Z]{1,6})[ -]?(\d{3,6})(?![\d])")


# --- match_albums.py:6644
def _folder_codes(name) -> set:
    return {f"{m.group(1)}{m.group(2)}".casefold() for m in _FOLDER_CODE.finditer(_IMAGE_SIZE.sub(" ", str(name or "")))
            if not _EDITION_YEAR.fullmatch(m.group(2))}


# --- match_albums.py:6649
def other_edition_scans(base, folder) -> bool:
    """EVI-11: a sub-folder of the album folder, holding no audio, named for another edition: the
    scans of that edition, kept for reference ("Bach - 6 Suites ... (2015 [2004])/scans, A 421
    (2004)": the 2004 CD's) - never your copy's print, so its barcode and numbers are not read.
    Another edition's name: a catalogue number the album folder's name does not carry ("A 421"),
    or a year the album folder's name gives nowhere together with an edition word ("reissue",
    "edition", "remaster" ...) or a country. Image sizes ("2000x2000", "2048px") are no years; a
    disc folder holding audio is your copy's disc."""
    try:
        rel = Path(folder).relative_to(base)
    except ValueError:
        return False
    if not rel.parts:
        return False
    own = _IMAGE_SIZE.sub(" ", Path(base).name)
    own_years, own_codes = set(_EDITION_YEAR.findall(own)), _folder_codes(own)
    at = Path(base)
    for part in rel.parts:
        at = at / part
        bare = _IMAGE_SIZE.sub(" ", part)
        years = set(_EDITION_YEAR.findall(bare))
        country = any(len(w) > 3 and w in mc._COUNTRY_NAMES for w in re.findall(r"[a-z]+", bare.casefold()))
        named = bool(_folder_codes(bare) - own_codes) or bool(
            years and not years & own_years and (_EDITION_WORD.search(bare) or country))
        if not named:
            continue
        try:
            if not any(q.suffix.lower() in AUDIO_EXT for q in at.iterdir()):
                return True
        except OSError:
            return False
    return False


# --- match_albums.py:6683
def list_images(base, max_n, inventory=None):
    """Every image under the album folder (subfolders included), most likely
    to carry a barcode or catalogue number first (ocr_order: the roles whose scans paid
    off most, learned). Exact duplicate files (e.g. 'scan 1 (copy).jpg') are scanned once.

    Returns (paths, key): the key identifies exactly these image contents, so
    OCR results can be cached and reused while the images are unchanged.
    inventory (a dict, SCN-1): filled with what was found - found (image files), duplicates
    (exact copies of another found), unique (found less duplicates and unreadable), listed,
    cap, left_out (unique images after the cap, not listed: not read) and unreadable (files
    that could not be read). A copy of a listed image is no image left out."""
    import hashlib
    found = []
    for dirpath, _d, names in os.walk(base):
        if other_edition_scans(base, dirpath):
            continue                                     # EVI-11
        for n in sorted(names):
            p = Path(dirpath) / n
            if p.suffix.lower() in IMAGE_EXT and not web_image(p):
                found.append(p)
    found = rank(found, tie=_scan_shape)
    seen, out, digests = set(), [], []
    unreadable = duplicates = left_out = 0
    rest = []
    for k, p in enumerate(found):
        try:
            digest = hashlib.md5(p.read_bytes()).hexdigest()
        except OSError:
            unreadable += 1
            continue
        if digest in seen:
            duplicates += 1
            continue
        seen.add(digest)
        out.append(str(p))
        digests.append(digest)
        _DIGESTS[str(p)] = digest
        if max_n and len(out) >= max_n:
            rest = found[k + 1:]
            break
    if rest:
        # SCN-1: the images after the cap are not read; each is a copy of one already seen or
        # a unique image left out. Only one of a size already seen can be a copy, so only those
        # are read for their contents (a box's 80 further scans are not all read over the network)
        # (of one size, the first 64 KiB told apart before the whole: same-size scans of a box,
        # uncompressed at one resolution, differ there)
        def head(q):
            with open(q, "rb") as fh:
                return hashlib.md5(fh.read(65536)).hexdigest()
        by_size = {}                                   # size -> {path: [head, digest]} (None: not read yet)
        for p in [Path(x) for x in out]:
            try:
                by_size.setdefault(p.stat().st_size, {})[str(p)] = [None, _DIGESTS.get(str(p))]
            except OSError:
                by_size.setdefault(None, {})[str(p)] = [None, _DIGESTS.get(str(p))]
        for p in rest:
            try:
                size = p.stat().st_size
                same = by_size.setdefault(size, {})
                mine = [None, None]
                if same:
                    mine[0] = head(p)
                    for q, hd in list(same.items()):
                        try:                           # another's failing read is no fault of this one
                            if hd[0] is None:
                                hd[0] = head(q)
                            if hd[0] == mine[0]:
                                if hd[1] is None:
                                    hd[1] = hashlib.md5(Path(q).read_bytes()).hexdigest()
                                if mine[1] is None:
                                    mine[1] = hashlib.md5(p.read_bytes()).hexdigest()
                        except OSError:
                            same.pop(q, None)          # (counted already, as listed or left out)
                    # (a listed image whose size could not be told: compared by its whole contents)
                    if None in by_size and mine[1] is None:
                        mine[1] = hashlib.md5(p.read_bytes()).hexdigest()
                elif None in by_size:
                    mine[1] = hashlib.md5(p.read_bytes()).hexdigest()
            except OSError:
                unreadable += 1
                continue
            if mine[1] is not None and any(hd[1] == mine[1] for g in (same, by_size.get(None) or {})
                                           for hd in g.values()):
                duplicates += 1
                continue
            same[str(p)] = mine
            left_out += 1
    if inventory is not None:
        inventory.update(found=len(found), duplicates=duplicates,
                         unique=len(found) - duplicates - unreadable, listed=len(out), cap=max_n,
                         left_out=left_out, unreadable=unreadable)
    key = hashlib.md5((OCR_VERSION + "|" + "|".join(digests)).encode()).hexdigest()
    return out, key


# --- match_albums.py:6779
# each scan's contents (md5), as list_images last read them: the per-scan cache keys
_DIGESTS = {}


# --- match_albums.py:6782
def _scan_digest(path):
    import hashlib
    d = _DIGESTS.get(str(path))
    if d is None:
        try:
            d = hashlib.md5(Path(path).read_bytes()).hexdigest()
        except OSError:
            d = "path:" + str(path)                   # not readable: a reading of nothing
        _DIGESTS[str(path)] = d
    return d


