def new_scan_log():
    """What OCR read on each scan of one album, for record: "read" the scans
    read (not from the cache) this time, "text" each scan's readings, "barcodes" the
    barcodes decoded on each, "no_bars" the scans already decoded without a result."""
    return {"read": set(), "text": {}, "barcodes": {}, "no_bars": set()}


# --- match_albums.py:6896
# SCN-1: a scan read with no text on it is cached as this, not "": before 0.8.56 a reading that
# failed in the read-ahead (_ScanReads) was cached as "" too, so a "" in the cache may be a
# failure - it is read again (once: what it gives is cached the new way). Readings with text
# keep their cached value. (A string, one space: an older TagMender sharing the cache joins it
# as a blank line, where a marker of another type would stop it.)
BLANK_READING = " "


# --- match_albums.py:6899
def _read_ahead_kinds():
    """The kinds _ScanReads reads ahead: only their "" can be a failure kept as a blank page."""
    return {page_kind("text"), page_kind("spines"), "barcode-digits", "disc-rings-4"}


# --- match_albums.py:6904
def _cached_reading(raw, kind):
    """A per-scan cache value as a reading; None: read it again (a "" of before 0.8.56 of a
    kind read ahead - a deep reading's "" was never a failure)."""
    v = json.loads(raw)
    if v == "" and kind in _read_ahead_kinds():
        return None
    return "" if isinstance(v, str) and not v.strip() else v


# --- match_albums.py:6913
def _cache_value(v):
    return json.dumps(BLANK_READING if v == "" else v)


# --- match_albums.py:6917
def each_scan(*args, **kw):
    """_each_scan, charged to the "ocr" stage of an album being timed (stagetimes): reading the scans."""
    with stagetimes.stage("ocr"):
        return _each_scan(*args, **kw)


# --- match_albums.py:6923
def _each_scan(db, kind, images, read, log=None, budget_s=None, ahead=None):
    """read(path) for each scan, cached per scan (its contents and the OCR version, so a
    scan read once is not read again wherever it is in the list), several at once.
    Returns the readings in the order of IMAGES; a scan not started within budget_s
    reads as "". The scans read now (not from the cache) go to log["read"].
    ahead: a _ScanReads that may have read some of them already (the same reading,
    and its own budget for the kind); the others are read here."""
    images = [str(p) for p in images]
    keys = [f"{kind}:{scan_key(p)}" for p in images]
    vals = [None] * len(images)
    if db is not None:
        db.execute("CREATE TABLE IF NOT EXISTS ocr_cache (key TEXT PRIMARY KEY, value TEXT)")
        for i, k in enumerate(keys):
            row = db.execute("SELECT value FROM ocr_cache WHERE key=?", (k,)).fetchone()
            if row:
                vals[i] = _cached_reading(row[0], kind)
    todo = [i for i, v in enumerate(vals) if v is None]
    started = time.time()

    def one(i):
        if budget_s is not None and time.time() - started > budget_s:
            return None
        try:
            return read(images[i]) or ""
        except Exception:
            return False                               # (failed: not read, not cached)
    got = ahead.take(kind, [images[i] for i in todo]) if ahead is not None and todo else {}
    rest = [i for i in todo if images[i] not in got]
    started = time.time()                              # (the budget of what is read here)
    done = dict(zip(rest, _pmap(one, rest)))
    for i in todo:
        v = got[images[i]] if images[i] in got else done[i]
        if v is None or v is False:
            vals[i] = ""                               # over the time budget, or failed: not read
            if log is not None:
                log.setdefault("unread", set()).add(images[i])
            continue
        vals[i] = v
        if db is not None:
            db.execute("INSERT OR REPLACE INTO ocr_cache VALUES (?,?)", (keys[i], _cache_value(v)))
        if log is not None:
            log["read"].add(images[i])
    if db is not None and todo:
        db.commit()
    if log is not None:
        for p, v in zip(images, vals):
            if v:
                log["text"].setdefault(p, []).append(v)
    return vals


# --- match_albums.py:7121
def decoded_barcodes(*args, **kw):
    """_scan_barcodes, charged to the "ocr" stage of an album being timed (stagetimes): reading the scans."""
    with stagetimes.stage("ocr"):
        return _scan_barcodes(*args, **kw)


# --- match_albums.py:7127
def _scan_barcodes(db, images, log=None):
    """ocr_barcodes(images), cached for exactly these scans ("barcodes3"), with the scan
    each code was decoded on noted in log["barcodes"]. A code an older reading ("barcodes2")
    decoded is kept; an older empty reading is read again once (the crops were tried only in
    a white margin then: Mekong Delta - Visions Fugitives, bars up to the label's edge)."""
    images = [str(p) for p in images]
    if not images:
        return set()
    key = images_key(images)

    def compute():
        codes = sorted(ocr_barcodes(images))           # (albums looked up at once share _DECODED_ON)
        where = {c: [p for p in list(_DECODED_ON.get(c, ())) if p in images] for c in codes}
        return {"codes": codes, "from": {c: min(images.index(p) for p in on) for c, on in where.items() if on}}
    if db is not None:
        db.execute("CREATE TABLE IF NOT EXISTS ocr_cache (key TEXT PRIMARY KEY, value TEXT)")
        row = db.execute("SELECT value FROM ocr_cache WHERE key=?", (f"barcodes2:{key}",)).fetchone()
        old = json.loads(row[0]) if row else None
        if isinstance(old, list):
            old = {"codes": old, "from": {}}
        if old and old.get("codes"):
            compute = (lambda old=old: old)
    value = _cached(db, "barcodes3", key, compute)
    if isinstance(value, list):                        # a reading stored as the codes alone
        value = {"codes": value, "from": {}}
    found = set(value.get("codes") or ())
    if log is not None:
        for c, i in (value.get("from") or {}).items():
            if isinstance(i, int) and 0 <= i < len(images):
                log["barcodes"].setdefault(str(images[i]), set()).add(c)
        if not found:
            log["no_bars"].update(str(p) for p in images)
    return found


# --- match_albums.py:7163
# the scan each barcode ocr_barcodes returned was decoded on (set as it returns)
_DECODED_ON = {}


# --- match_albums.py:7166
def barcode_from_symbol(kind, data):
    """The barcode a decoded symbol stands for, or "" when its check digit fails (noise).
    A UPC-E is kept as the UPC-A it is short for: that is how the databases list it."""
    code = re.sub(r"\D", "", str(data or ""))
    if not mc.valid_barcode(code, kind):
        return ""
    # zbar may hand a UPC-E back already expanded (12 or 13 digits): kept as read
    return mc.upce_to_upca(code) if kind == "UPCE" and len(code) == 8 else code


# --- match_albums.py:7176
def _decoded_barcodes(decode, image, symbols):
    found = set()
    for d in decode(image, symbols=symbols):
        code = barcode_from_symbol(d.type, d.data.decode("ascii", "ignore"))
        if code:
            found.add(code)
    return found


# --- match_albums.py:7185
def _barcode_variants(im):
    """Progressively more effortful versions of one scan. A barcode is often a
    small part of a big page, slightly blurred, or tiny: enlarge it, sharpen
    it, and try each part of the page on its own."""
    from PIL import Image, ImageFilter, ImageOps
    gray = ImageOps.grayscale(im)
    yield gray
    enhanced = ImageOps.autocontrast(gray).filter(ImageFilter.UnsharpMask(radius=2, percent=180))
    yield enhanced
    w, h = gray.size
    longest = max(w, h)
    for scale in (2, 3):
        if longest * scale <= 6500:
            yield enhanced.resize((w * scale, h * scale), Image.LANCZOS)
    # overlapping tiles (3x3 grid, 50% overlap), each enlarged to ~2400px
    tw, th = w // 2, h // 2
    for gx in range(3):
        for gy in range(3):
            x0, y0 = min(gx * tw // 2 * 1, w - tw), min(gy * th // 2 * 1, h - th)
            tile = enhanced.crop((x0, y0, x0 + tw, y0 + th))
            factor = max(1.0, min(3.0, 2400 / max(tile.size)))
            if factor > 1.0:
                tile = tile.resize((int(tile.size[0] * factor), int(tile.size[1] * factor)), Image.LANCZOS)
            yield tile


# --- match_albums.py:7211
def ocr_barcodes(paths, per_image_s=8.0, total_s=40.0, patches_s=60.0):
    """Decode product barcodes from scans. Returns validated codes only.

    Stops at the first image that yields one. Time-boxed (the bar patches of all
    scans in `patches_s`, then whole pages in `total_s`), because an image with no
    readable barcode would otherwise cost the full multi-pass search."""
    try:
        from PIL import Image
        from pyzbar.pyzbar import decode, ZBarSymbol
    except ImportError:
        return set()
    symbols = [ZBarSymbol.EAN13, ZBarSymbol.EAN8, ZBarSymbol.UPCA, ZBarSymbol.UPCE]

    def codes_in(img):
        found = set()
        for rotation in (0, 90, 180, 270):
            v = img if rotation == 0 else img.rotate(rotation, expand=True)
            try:
                found |= _decoded_barcodes(decode, v, symbols)
            except Exception:
                continue
            if found:
                break
        return found

    # First where barcodes ARE: the bar patches of every scan, found cheaply and decoded
    # on their own (Enslaved - Axioma Ethica Odini: nine 7019x5100 scans; the whole-page
    # passes used the time budget up before the 8th, the back of the digipak). Upright or
    # sideways, the bars cut out alone first: zbar fails on a printed frame or a busy
    # picture beside them, which page passes cannot avoid.
    with_bars, started = [], time.time()
    for p in paths:
        if time.time() - started > patches_s:
            break
        try:
            im = Image.open(p)
            im.load()
            if im.mode not in ("RGB", "L"):
                im = im.convert("RGB")
        except Exception:
            continue
        patches = barcode_patches(im)
        if patches:
            with_bars.append(p)
        for g, box, _turned in patches:
            if time.time() - started > patches_s:
                break                              # a scan full of bar-like lines: stop within it too
            for crop in _bar_crops(g, box):
                try:
                    hit = _decoded_barcodes(decode, crop, symbols)
                except Exception:
                    continue
                if hit:
                    return _decoded_on(hit, p)
            x0, y0, x1, y1 = box
            bw, bh = x1 - x0, y1 - y0
            crop = g.crop((int(max(0, x0 - bw * 0.3)), int(max(0, y0 - bh * 0.5)),
                           int(min(g.width, x1 + bw * 0.3)), int(min(g.height, y1 + bh * 0.8))))
            for variant in list(_barcode_variants(crop))[:4]:
                hit = codes_in(variant)
                if hit:
                    return _decoded_on(hit, p)
    # then whole pages, those with bar patches first: within the time box, the likely
    # scans are read before a run of booklet pages uses it up (Alcest - Les Chants De
    # L'aurore: the obi was the tenth of ten scans)
    paths = with_bars + [p for p in paths if p not in with_bars]
    started = time.time()
    for p in paths:
        if time.time() - started > total_s:
            break
        try:
            im = Image.open(p)
            im.load()
            if im.mode not in ("RGB", "L"):
                im = im.convert("RGB")
        except Exception:
            continue
        t_img = time.time()
        small = max(im.size) < 1000          # too few pixels for the heavy passes
        hit = set()
        for n, variant in enumerate(_barcode_variants(im)):
            if n >= 2 and small:
                break
            for rotation in (0, 90, 180, 270):
                if time.time() - t_img > per_image_s:
                    break
                v = variant if rotation == 0 else variant.rotate(rotation, expand=True)
                try:
                    hit |= _decoded_barcodes(decode, v, symbols)
                except Exception:
                    continue
                if hit:
                    break
            if hit or time.time() - t_img > per_image_s:
                break
        if hit:
            return _decoded_on(hit, p)
    return set()


# --- match_albums.py:7311
def _decoded_on(codes, path):
    for c in codes:
        _DECODED_ON.setdefault(c, set()).add(str(path))
    return codes


# --- match_albums.py:7317
_LANGS = None


# --- match_albums.py:7320
def ocr_langs():
    """English, plus Russian and Japanese when their tesseract packs are installed
    (tesseract-ocr-rus, tesseract-ocr-jpn): FONO sleeves, Japanese obi strips."""
    global _LANGS
    if _LANGS is None:
        import subprocess
        try:
            have = subprocess.run(["tesseract", "--list-langs"], capture_output=True, text=True,
                                  timeout=30).stdout.split()
        except Exception:
            have = []
        _LANGS = "+".join(x for x in ("eng", "rus", "jpn") if x in have) or "eng"
    return _LANGS


# --- match_albums.py:7337
# OCR-3: each scan is read in its own script. The language packs of scripts other than the
# Latin alphabet, by the script tesseract's OSD names; every other pack is a Latin one.
_SCRIPT_PACKS = {"Cyrillic": {"rus", "ukr", "bul", "srp", "mkd", "bel"},
                 "Japanese": {"jpn", "jpn_vert"}, "Hiragana": {"jpn", "jpn_vert"},
                 "Katakana": {"jpn", "jpn_vert"},
                 "Han": {"chi_sim", "chi_tra", "chi_sim_vert", "chi_tra_vert", "jpn", "jpn_vert"},
                 "Hangul": {"kor", "kor_vert"}, "Greek": {"ell", "grc"}, "Arabic": {"ara", "fas", "urd"},
                 "Hebrew": {"heb", "yid"}}


# --- match_albums.py:7343
_NON_LATIN = set().union(*_SCRIPT_PACKS.values())


# --- match_albums.py:7344
OSD_MIN_CONFIDENCE = 1.0      # under it OSD's script is a guess (a German label read as "Japanese, 0.25")


# --- match_albums.py:7345
PAGE_OCR = "p3"               # the page text's and spines' reading (OCR-3: colour, own script); in their kinds


# --- match_albums.py:7348
def page_kind(base):
    """The cache kind of a page reading ("text", "spines", "cover"): the reading's version and
    the language set, so readings made another way (greyscale, every pack at once) are not reused."""
    return f"{base}-{PAGE_OCR}-{ocr_langs()}"


# --- match_albums.py:7354
def _latin_langs(langs):
    """The Latin-alphabet packs of a language set ("eng+deu" of "eng+deu+rus+jpn"), English
    at least."""
    return "+".join([x for x in langs.split("+") if x not in _NON_LATIN] or ["eng"])


# --- match_albums.py:7360
def _open_reduced(path, box):
    """A scan in colour (RGB), at most BOX pixels, reduced BEFORE it is converted (a JPEG
    decoded at a fraction of its size, the rest shrunk first), so a 6000 x 6000 scan is never
    held in colour at full size. Returns (image, its original size, its dpi or None)."""
    from PIL import Image
    with Image.open(path) as src:
        size, dpi = src.size, src.info.get("dpi")
        try:
            src.draft("RGB", box)                     # (JPEG: decoded reduced; others: no-op)
        except Exception:
            pass
        im = src
        if im.mode not in ("1", "P"):                 # (palette images are shrunk in colour)
            try:
                im = im.copy()
                im.thumbnail(box)
            except Exception:
                im = src
        im = im.convert("RGB")
    im.thumbnail(box)
    return im, size, dpi


# --- match_albums.py:7383
def _page_image(path):
    """A scan as tesseract reads it best: in colour (tesseract picks the channel the print
    stands out in; a greyscale copy loses blue-on-black print: Popol Vuh's label) at most
    2400 pixels, with its resolution carried over. Returns (image, save options)."""
    im, (w, _h), dpi = _open_reduced(path, (2400, 2400))
    opts = {}
    try:
        if dpi and float(dpi[0]) >= 50:
            opts["dpi"] = (round(float(dpi[0]) * im.size[0] / max(w, 1)),) * 2
    except (TypeError, ValueError, IndexError):
        pass
    return im, opts


# --- match_albums.py:7397
def scan_script(png):
    """The script tesseract's OSD finds on an image file ("Latin", "Cyrillic", "Japanese"...),
    or "" when it finds none (too little text) or is unsure (OSD_MIN_CONFIDENCE)."""
    try:
        r = _tesseract(["tesseract", str(png), "stdout", "--psm", "0"], capture_output=True, text=True,
                       timeout=30, env=_tess_env())
    except Exception:
        return ""
    m = re.search(r"^Script: (\w+)\s*$", r.stdout or "", re.M)
    c = re.search(r"^Script confidence: ([\d.]+)", r.stdout or "", re.M)
    if not m or not c or float(c.group(1)) < OSD_MIN_CONFIDENCE:
        return ""
    return m.group(1)


# --- match_albums.py:7412
def _osd_script(im, opts, png=None):
    """scan_script of a page image (_page_image's), on a copy at most 1600 pixels: OSD on a
    whole 2400-pixel back cover took over a second, on that copy about half."""
    import tempfile
    if png is not None and max(im.size) <= 1600:
        return scan_script(png)
    small = im.copy()
    small.thumbnail((1600, 1600))
    o = dict(opts)
    if "dpi" in o:
        o["dpi"] = (max(50, round(o["dpi"][0] * small.size[0] / max(im.size[0], 1))),) * 2
    with tempfile.NamedTemporaryFile(suffix=".png") as tmp:
        small.save(tmp.name, **o)
        return scan_script(tmp.name)


# --- match_albums.py:7428
def _tess_page(png, langs, timeout=120):
    """tesseract's sparse-text reading of an image file in LANGS: (text, words), words being
    (confidence, word) of each word read."""
    import tempfile
    with tempfile.TemporaryDirectory() as d:
        out = os.path.join(d, "page")
        _tesseract(["tesseract", str(png), out, "--psm", "11", "-l", langs, "txt", "tsv"],
                   capture_output=True, text=True, timeout=timeout, env=_tess_env())
        try:
            text = Path(out + ".txt").read_text(encoding="utf-8", errors="replace")
        except OSError:
            text = ""
        words = []
        try:
            for row in Path(out + ".tsv").read_text(encoding="utf-8", errors="replace").splitlines()[1:]:
                f = row.split("\t")
                if len(f) >= 12 and f[0] == "5" and f[11].strip():
                    try:
                        words.append((float(f[10]), f[11].strip()))
                    except ValueError:
                        continue
        except OSError:
            pass
    return text, words


# --- match_albums.py:7454
_LATIN_WORD = re.compile(r"[A-Za-z][a-z]{2,}|[A-Z]{3,}")


# --- match_albums.py:7457
def _latin_poor(words):
    """Too little read in the Latin alphabet to trust: fewer than three sure (confidence 70)
    words of three letters or codes."""
    good = [w for c, w in words if c >= 70 and (_LATIN_WORD.fullmatch(w.strip(".,:;()'\"")) or
                                                _CODE_LIKE.fullmatch(w.strip(".,:;()")))]
    return len(good) < 3


# --- match_albums.py:7465
def _sure_chars(words):
    """How much a reading read for sure: the letters and digits of its words of confidence 70
    (not the long-vowel marks and dots noise reads as "ーー")."""
    return sum(n for c, w in words if c >= 70
               for n in [sum(ch.isalnum() and ch not in "ー〜・" for ch in w)] if n)


# --- match_albums.py:7475
# OCR-3: one decision per scan and language set, shared by its page text and its spines:
# (scan digest, language set) -> (the packs chosen, the page text). The first to ask reads the
# page (one OSD a scan); the other waits for it and takes its reading. The newest 256 kept.
_SCAN_PAGES = {}


# --- match_albums.py:7476
_SCAN_PAGE_LOCKS = {}


# --- match_albums.py:7477
_SCAN_PAGES_GUARD = threading.Lock()


# --- match_albums.py:7478
_SCAN_PAGES_MAX = 256


# --- match_albums.py:7481
def _read_page(path):
    """scan_page's reading, not shared: (packs chosen, text)."""
    import tempfile
    langs = ocr_langs()
    latin = _latin_langs(langs)
    im, opts = _page_image(path)
    with tempfile.NamedTemporaryFile(suffix=".png") as tmp:
        im.save(tmp.name, **opts)
        if latin == langs:
            return latin, _tess_page(tmp.name, latin)[0]
        script = _osd_script(im, opts, tmp.name)
        own = [x for x in langs.split("+") if x in _SCRIPT_PACKS.get(script, ())]
        if script == "Latin":
            return latin, _tess_page(tmp.name, latin)[0]
        if own:
            chosen = "+".join(own + ["eng"])
            return chosen, _tess_page(tmp.name, chosen)[0]
        text, words = _tess_page(tmp.name, latin)
        if _latin_poor(words):
            text_all, words_all = _tess_page(tmp.name, langs)
            if _sure_chars(words_all) >= max(6, 1.5 * _sure_chars(words) + 1):
                # the Latin reading is kept with it: what it read is never lost
                return langs, text_all + "\n" + text
        return latin, text


# --- match_albums.py:7507
def scan_page(path):
    """OCR-3: one scan's page text, read in its own script. Returns (langs, text). With only
    Latin packs set, it is read in those. Otherwise OSD names the script: Latin is read in
    the Latin packs alone, another script in its packs and English; with no sure script, in
    the Latin packs first and, only when that reads too little, in every pack too, which is
    kept (with the Latin reading) when it reads clearly more for sure. A Latin cover is never
    read only through every pack at once. Read once a scan: its spines (scan_langs) take the
    packs chosen here."""
    key = (_scan_digest(path), ocr_langs())
    with _SCAN_PAGES_GUARD:
        lock = _SCAN_PAGE_LOCKS.setdefault(key, threading.Lock())
    with lock:
        with _SCAN_PAGES_GUARD:
            got = _SCAN_PAGES.get(key)
        if got is None:
            got = _read_page(path)
            with _SCAN_PAGES_GUARD:
                _SCAN_PAGES[key] = got
                while len(_SCAN_PAGES) > _SCAN_PAGES_MAX:
                    old = next(iter(_SCAN_PAGES))
                    _SCAN_PAGES.pop(old)
                    _SCAN_PAGE_LOCKS.pop(old, None)
    return got


# --- match_albums.py:7532
def scan_langs(path):
    """The packs a scan's spines are read in: those its page text was read in (scan_page,
    which reads the page now when nobody has yet). Only Latin packs set: those, unread."""
    langs = ocr_langs()
    latin = _latin_langs(langs)
    if latin == langs:
        return latin
    try:
        return scan_page(path)[0]
    except Exception:
        return latin


# --- match_albums.py:7545
def ocr_spines(paths):
    """Text printed along the spines of a CD tray card (catalogue numbers often
    appear only there), which page OCR misses: it runs sideways. Each side strip
    of a landscape scan is cut off, turned upright, enlarged and read."""
    import subprocess
    import tempfile
    try:
        from PIL import Image
    except ImportError:
        return ""
    chunks = []
    for p in paths:
        try:
            with Image.open(p) as src:
                w, h = src.size
        except Exception:
            continue
        spread = w / max(h, 1) >= 1.8 and w >= 1200
        if not spread and (not (1.15 <= w / max(h, 1) <= 1.6) or w < 600):
            continue                                   # tray cards are about 151 x 118 mm
        try:
            # in colour, as the page, and in the packs its page was read in (OCR-3); never
            # larger than read (a spread at 3600, a tray card's strips at 3000 tall at most)
            im = _open_reduced(p, (3600, 3600) if spread else (int(4000 * w / max(h, 1)), 4000))[0]
            langs = scan_langs(p)
        except Exception:
            continue
        w, h = im.size
        if spread:
            # a digipak or booklet spread scanned open: its spine runs down the middle
            # (Cryptopsy - Tome II: "HHR 2018-23" only there). Read the whole spread sideways.
            whole = im.copy()
            whole.thumbnail((3600, 3600))
            for angle in (90, 270):
                try:
                    with tempfile.NamedTemporaryFile(suffix=".png") as tmp:
                        whole.rotate(angle, expand=True).save(tmp.name)
                        r = _tesseract(["tesseract", tmp.name, "stdout", "--psm", "11", "-l", langs],
                                           capture_output=True, text=True, timeout=120, env=_tess_env())
                    chunks.append(r.stdout)
                except Exception:
                    continue
            continue
        strip_w = max(int(w * 0.07), 30)
        for box in ((0, 0, strip_w, h), (w - strip_w, 0, w, h)):
            strip = im.crop(box)
            scale = max(1.0, min(3.0, 3000 / h))
            if scale > 1.0:
                strip = strip.resize((int(strip.size[0] * scale), int(strip.size[1] * scale)))
            for angle in (90, 270):
                try:
                    with tempfile.NamedTemporaryFile(suffix=".png") as tmp:
                        strip.rotate(angle, expand=True).save(tmp.name)
                        r = _tesseract(["tesseract", tmp.name, "stdout", "--psm", "11", "-l", langs],
                                           capture_output=True, text=True, timeout=60, env=_tess_env())
                    chunks.append(r.stdout)
                except Exception:
                    continue
    return "\n".join(chunks)


# --- match_albums.py:7606
def barcode_regions(im, max_regions=3):
    """Where barcodes are on a scan: patches of dense vertical bars (strong horizontal
    contrast, weak vertical contrast), found on a small copy. Returns boxes in the
    image's own pixels, largest first. Needs numpy; without it, none."""
    try:
        import numpy as np
        from PIL import ImageFilter
    except ImportError:
        return []
    from collections import deque
    g = im.convert("L")
    W, H = g.size
    s = 1200 / max(W, H, 1)
    a = np.asarray(g.resize((max(1, int(W * s)), max(1, int(H * s)))), dtype=np.float32)
    if a.shape[0] < 3 or a.shape[1] < 3:
        return []
    gx = np.abs(np.diff(a, axis=1))[:-1, :]
    gy = np.abs(np.diff(a, axis=0))[:, :-1]
    energy = Image_from(np.uint8(np.clip(np.clip(gx - gy, 0, None) * 2, 0, 255))).filter(ImageFilter.BoxBlur(6))
    m = np.asarray(energy) > 60
    h, w = m.shape
    seen = np.zeros_like(m, bool)
    found = []
    for y in range(0, h, 2):
        for x in range(0, w, 2):
            if not m[y, x] or seen[y, x]:
                continue
            q, ys, xs = deque([(y, x)]), [], []
            seen[y, x] = True
            while q:
                cy, cx = q.popleft()
                ys.append(cy)
                xs.append(cx)
                for ny, nx in ((cy + 1, cx), (cy - 1, cx), (cy, cx + 1), (cy, cx - 1)):
                    if 0 <= ny < h and 0 <= nx < w and m[ny, nx] and not seen[ny, nx]:
                        seen[ny, nx] = True
                        q.append((ny, nx))
            x0, x1, y0, y1 = min(xs), max(xs), min(ys), max(ys)
            bw, bh = x1 - x0, y1 - y0
            if len(ys) > 150 and bw > 20 and bh > 8 and len(ys) > 0.5 * bw * bh:
                found.append((len(ys), (x0 / s, y0 / s, x1 / s, y1 / s)))
    found = _merge_bar_rows(found)
    found.sort(reverse=True)
    return [b for _n, b in found[:max_regions]]


# --- match_albums.py:7652
def _merge_bar_rows(found):
    """Patches side by side on one row joined into one: wide black bars have no edges
    inside, so a big barcode is found as two or three pieces (Lamb of God - Omens, Alcest's
    obi). `found` holds (pixels, box) pairs; the joined patch sums the pixels."""
    found = list(found)
    joined = True
    while joined:
        joined = False
        for i in range(len(found)):
            for j in range(i + 1, len(found)):
                (na, a), (nb, b) = found[i], found[j]
                overlap = min(a[3], b[3]) - max(a[1], b[1])
                gap = max(a[0], b[0]) - min(a[2], b[2])
                if overlap >= 0.5 * min(a[3] - a[1], b[3] - b[1]) and gap <= 0.6 * max(a[3] - a[1], b[3] - b[1]):
                    found[i] = (na + nb, (min(a[0], b[0]), min(a[1], b[1]), max(a[2], b[2]), max(a[3], b[3])))
                    del found[j]
                    joined = True
                    break
            if joined:
                break
    return found


# --- match_albums.py:7675
def barcode_patches(im, max_regions=3):
    """The barcodes on a scan, each with its bars standing upright: (grey image, box,
    turned) triples. A barcode printed sideways, along a tray card's edge (BTBAM - The Great
    Misdirect), is found on the scan turned a quarter."""
    from PIL import Image
    g = im.convert("L")
    out = [(g, b, False) for b in barcode_regions(g, max_regions)]
    turned = g.transpose(Image.ROTATE_90)
    out += [(turned, b, True) for b in barcode_regions(turned, max_regions)]
    return out


# --- match_albums.py:7687
def _bars_span(g, box):
    """Where the bars of the barcode found at `box` start and end, as (left, right,
    module, inner left, inner right; see _lone_edge_lines): walked out along the middle rows from the patch until a white gap wider
    than any inside it (the quiet zone round a barcode is 7+ bar widths; inside, gaps
    are at most 4). The patch found may be half the code, or run into a printed frame
    (Candlemass's digipak). None when the patch holds no bars."""
    import numpy as np
    x0, y0, x1, y1 = (int(v) for v in box)
    bw, bh = x1 - x0, y1 - y0
    lo, hi = int(max(0, x0 - 1.5 * bw)), int(min(g.width, x1 + 1.5 * bw))
    top, bottom = int(y0 + bh * 0.3), int(y1 - bh * 0.3)
    if hi - lo < 10 or bottom <= top:
        return None
    profile = np.asarray(g.crop((lo, top, hi, bottom)), dtype=np.float32).mean(axis=0)
    inside = profile[x0 - lo:x1 - lo]
    if len(inside) < 10:
        return None
    p10, p90 = np.percentile(inside, [10, 90])
    if p90 - p10 < 30:
        return None
    dark = profile < (p10 + p90) / 2
    gaps, run = [], 0
    for d in dark[x0 - lo:x1 - lo]:
        if not d:
            run += 1
        elif run:
            gaps.append(run)
            run = 0
    marks = np.nonzero(dark)[0]
    if not gaps or not len(marks):
        return None
    quiet = max(4.0, 1.6 * max(gaps))
    start = int(marks[np.argmin(np.abs(marks - ((x0 + x1) // 2 - lo)))])
    left = right = start
    for i in range(start, len(dark)):
        if dark[i]:
            right = i
        elif i - right > quiet:
            break
    for i in range(start, -1, -1):
        if dark[i]:
            left = i
        elif left - i > quiet:
            break
    module = max(1, min(gaps))
    inner_left, inner_right = _lone_edge_lines(dark, left, right, module)
    return lo + left, lo + right + 1, module, lo + inner_left, lo + inner_right + 1


# --- match_albums.py:7736
def _lone_edge_lines(dark, left, right, module):
    """The span without a lone line at either end: a frame drawn a few bar widths from
    the bars is walked into as one more bar. Returns (left, right) inside it; the
    same ends when there is none."""
    def next_run(i, step):
        while left <= i <= right and dark[i]:
            i += step
        gap = 0
        while left <= i <= right and not dark[i]:
            i, gap = i + step, gap + 1
        return i, gap
    i, gap = next_run(left, 1)
    inner_left = i if gap >= 3 * module and i < right else left
    i, gap = next_run(right, -1)
    inner_right = i if gap >= 3 * module and i > inner_left else right
    return inner_left, inner_right


# --- match_albums.py:7754
def _bar_crops(g, box):
    """Crops of one barcode for the decoder, closest first, each in a white margin: the
    bars alone (a frame, a sticker's edge or a busy picture beside them stops zbar), then
    slightly narrower and wider spans, as the patch found is seldom exact; small ones
    also enlarged."""
    from PIL import Image, ImageOps
    x0, y0, x1, y1 = box
    bw, bh = x1 - x0, y1 - y0
    spans = []
    found = _bars_span(g, box)
    if found:
        left, right, module, inner_left, inner_right = found
        spans.append((left - 2 * module, right + 2 * module))
        if (inner_left, inner_right) != (left, right):         # without a frame's line
            spans += [(inner_left - module, inner_right + module), (inner_left - module, right + 2 * module),
                      (left - 2 * module, inner_right + module)]
    spans += [(x0 - bw * m, x1 + bw * m) for m in (-0.02, 0.03, 0.1, 0.2, 0.35)]
    for a, b in spans:
        a, b = int(max(0, a)), int(min(g.width, b))
        for inset in (0.1, 0.3):
            c = g.crop((a, int(y0 + bh * inset), b, int(y1 - bh * inset)))
            if c.width < 8 or c.height < 4:
                continue
            bare = c
            c = ImageOps.expand(c, border=max(12, int((b - a) * 0.08)), fill=255)
            yield c
            if c.width < 900:
                yield c.resize((c.width * 2, c.height * 2), Image.LANCZOS)
            # as cut, too: a barcode with little white beside it (its label's edge a few bar
            # widths away) is read as one more bar once a white margin is put round that edge
            # (Mekong Delta - Visions Fugitives: the dark spine 4 bar widths after the bars)
            yield bare


# --- match_albums.py:7788
def Image_from(arr):
    from PIL import Image
    return Image.fromarray(arr)


# --- match_albums.py:7793
def _digit_band_reads(g, box):
    """tesseract's readings of the digits under one upright barcode: the patch with its
    surroundings enlarged, and tight bands at the foot of the bars, read as a line and
    as digits only."""
    x0, y0, x1, y1 = box
    bw, bh = x1 - x0, y1 - y0
    crop = g.crop((int(max(0, x0 - bw * 0.15)), int(max(0, y0 - bh * 0.4)),
                   int(min(g.width, x1 + bw * 0.15)), int(min(g.height, y1 + bh * 0.6))))
    crops = [(crop.resize((crop.width * 2, crop.height * 2)), 6, "")]
    # the digits alone: a tight band at the foot of the bars, at the scan's own
    # resolution (Exhorder's Dissonance digipak: enlarged, or with the bars in
    # view, tesseract reads noise; the band alone reads "5 013929 020160")
    for f0, f1 in ((-0.1, 0.3), (-0.05, 0.35), (0.0, 0.3)):
        band = (int(max(0, x0 - bw * 0.15)), int(max(0, y1 + bh * f0)),
                int(min(g.width, x1 + bw * 0.1)), int(min(g.height, y1 + bh * f1)))
        if band[3] - band[1] > 8:
            crops.append((g.crop(band), 7, ""))
            crops.append((g.crop(band), 7, "0123456789"))   # no letters for a smudged digit
    out = []
    for c, psm, only in crops:
        try:
            out.append(_tess(c, psm, only=only))
        except Exception:
            continue
    return out


# --- match_albums.py:7820
def ocr_barcode_digits(paths, max_images=15, budget_s=120.0):
    """The digits printed under a barcode, read from the barcode's own patch at full
    resolution (page OCR on a reduced scan misses them: Cryptopsy - Tome II's
    8715392182327). For when no barcode decoder (pyzbar) is installed, or it read none.
    A sideways barcode is read turned upright both ways (its digits may run up or down)."""
    try:
        from PIL import Image
    except ImportError:
        return ""
    chunks, started = [], time.time()
    for p in list(paths)[:max_images]:
        if time.time() - started > budget_s:
            break
        try:
            im = Image.open(p)
            im.load()
        except Exception:
            continue
        for g, box, turned in barcode_patches(im):
            frames = [(g, box)]
            if turned:
                x0, y0, x1, y1 = box
                frames.append((g.transpose(Image.ROTATE_180), (g.width - x1, g.height - y1, g.width - x0, g.height - y0)))
            for frame, fbox in frames:
                # checked before each read too: one scan holds up to six patches, 7 reads each
                if time.time() - started > budget_s:
                    break
                chunks += _digit_band_reads(frame, fbox)
    # the first digit sits apart and is often misread: complete 6+6 digit groups by
    # the check digit - groups read on ONE line only (OCR-5): two crops each reading the left
    # group "006759" once joined into an invented "2006759006759"
    text = "\n".join(chunks)
    for m in re.finditer(r"(?<!\d)(\d{6})[^\d\n]{0,3}(\d{6})(?!\d)", text):
        code = mc.complete_ean(m.group(1) + m.group(2))
        if code:
            chunks.append(mc.COMPLETED + code)
    return "\n".join(chunks)


# --- match_albums.py:7859
def find_disc(g):
    """A disc on a scan as (centre x, centre y, radius) in the image's own pixels, from
    the extent of everything darker than the scanner's lid; None when the scan is not
    a disc (too little of it, or not round)."""
    try:
        import numpy as np
    except ImportError:
        return None
    s = 800 / max(g.size)
    small = np.asarray(g.resize((max(1, int(g.width * s)), max(1, int(g.height * s)))), dtype=np.float32)
    ys, xs = np.nonzero(small < 235)
    if len(xs) < 1000:
        return None
    x0, x1 = np.percentile(xs, [0.5, 99.5])
    y0, y1 = np.percentile(ys, [0.5, 99.5])
    w, h = x1 - x0, y1 - y0
    if min(w, h) < 0.5 * min(small.shape) or not 0.85 <= w / max(h, 1) <= 1.15:
        return None
    return (x0 + x1) / 2 / s, (y0 + y1) / 2 / s, min(w, h) / 2 / s


# --- match_albums.py:7880
def unwrap_ring(g, cx, cy, r0, r1):
    """The ring between radii r0 and r1 laid out flat, outer edge up, so text printed
    round the hub reads left to right; the start is repeated at the end, so a line
    crossing the cut is read whole."""
    import numpy as np
    a = np.asarray(g, dtype=np.uint8)
    n, rows = int(2 * np.pi * r1), int(r1 - r0)
    if n < 50 or rows < 8:
        return None
    th = np.linspace(0, 2 * np.pi, n, endpoint=False)
    th = np.concatenate([th, th[: n // 4]])
    T, R = np.meshgrid(th, np.linspace(r1, r0, rows))
    X = np.clip(cx + R * np.cos(T), 0, a.shape[1] - 1).astype(int)
    Y = np.clip(cy + R * np.sin(T), 0, a.shape[0] - 1).astype(int)
    return Image_from(a[Y, X])


# --- match_albums.py:7897
def ocr_disc_rings(paths, max_images=8, budget_s=60.0):
    """The matrix / runout codes etched or printed round a disc's hub (Exhorder's
    Dissonance CD: "QDISS0201CDD-1 15 A00"), which page OCR cannot read because the
    text runs in a circle: the ring is unwrapped from the disc's centre and read flat.
    The rim is read too: catalogue numbers and the maker's line are printed along the
    edge (Lamb of God - Omens: "NB 6570-2"; Alcest's "Made in Japan GQCS-91470").
    Time-boxed (`budget_s` for all discs): a rim strip of a big scan is a slow read."""
    try:
        from PIL import Image
        import numpy  # noqa: F401
    except ImportError:
        return ""
    chunks, discs, started = [], 0, time.time()
    for p in list(paths)[:40]:
        if discs >= max_images or time.time() - started > budget_s:
            break
        try:
            g = Image.open(p).convert("L")
        except Exception:
            continue
        # (a hub close-up may be small: OCR-7 reads one of 555 px; the whole-ring strips need 800)
        if not 0.8 <= g.width / max(g.height, 1) <= 1.25 or min(g.size) < 400:
            continue
        found = find_disc(g)
        if not found:
            continue
        discs += 1
        cx, cy, r = found
        if min(g.size) >= 800:
            for strip in _hub_strips(g, cx, cy, r) + _rim_strips(g, cx, cy, r):
                if time.time() - started > budget_s:
                    break
                try:
                    chunks.append(_tess(strip, 11))
                except Exception:
                    continue
        if time.time() - started <= budget_s:
            chunks.append(ocr_hub_closeup(g, found, started + budget_s))
    return "\n".join(c for c in chunks if c)


# --- match_albums.py:7938
def _hub_strips(g, cx, cy, r):
    """The ring round the hub laid flat, twice, and once for text running the other way."""
    from PIL import Image
    out = []
    # (a band a little further out too: a printed hub line on a wide clamping ring sits there,
    # and the inner bands cut through it - Pallas - wearewhoweare: "398478 @1 MTS5503")
    # OCR-6: and a band well out from the hub, for a close-up of the hub that fills the scan:
    # the disc found is then the frame, and the matrix runs at about 0.7-0.86 of it, between
    # the hub bands and the rim (Opeth - Blackwater Park, Legacy Edition: "A0102309767-0102
    # 13 A00", Sony DADC, read nowhere else)
    for f0, f1, flip in ((0.28, 0.40, False), (0.30, 0.38, False), (0.28, 0.40, True), (0.33, 0.42, False),
                         (0.70, 0.86, False)):
        if flip:                                   # text running the other way round
            strip = unwrap_ring(g.transpose(Image.FLIP_LEFT_RIGHT), g.width - cx, cy, r * f0, r * f1)
            strip = strip.rotate(180) if strip is not None else None
        else:
            strip = unwrap_ring(g, cx, cy, r * f0, r * f1)
        if strip is not None:
            out.append(strip)
    return out


# --- match_albums.py:7960
def _rim_strips(g, cx, cy, r):
    """The band along a disc's edge laid flat, read as it comes and upside down (text on
    the lower half is often printed to read from inside). A big scan is reduced first, a
    small one's band enlarged, so the letters come out about the size tesseract reads best."""
    from PIL import Image
    scale = min(1.0, 1500 / max(r, 1))
    if scale < 1.0:
        g = g.resize((int(g.width * scale), int(g.height * scale)), Image.LANCZOS)
        cx, cy, r = cx * scale, cy * scale, r * scale
    strip = unwrap_ring(g, cx, cy, r * 0.85, r * 1.02)      # find_disc may find it a little small
    if strip is None:
        return []
    if r < 900:
        strip = strip.resize((strip.width * 2, strip.height * 2), Image.LANCZOS)
    return [strip, strip.rotate(180)]


# --- match_albums.py:7986
# OCR-7: a close-up of the hub, read band by band. The ring is laid flat round a centre
# fitted to the disc's own rings (a close-up cut off at the scan's edge puts find_disc's centre
# off, and the text then wanders up and down the strip); the strip is cut where a ring's edge
# runs all the way round, each band into the runs of marks along it, and each run is read
# tight, its letters brought to one height, as light print on dark and dark on light, in the
# four ways it can run (as it comes, upside down, mirrored - a matrix photographed through the
# disc - and both). Thin stencil letters on a hub read nowhere else (Creedence Clearwater
# Revival - Chronicle, Volume Two: "MASTERED BY MAYKING"; Univers Zero - Heatwave, a 555 px
# photo: "U.S. OPTICAL DISC").
HUB_R = 700.0                       # the disc brought to this radius before its rings are found


# --- match_albums.py:7987
HUB_BAND = (0.25, 0.97)             # the part of the radius laid flat


# --- match_albums.py:7988
HUB_LETTERS = (13.0, 16.0)          # letter heights each run is read at (px)


# --- match_albums.py:7989
HUB_FIT = 0.04                      # a close-up: the rings fit a circle within 4% of the radius


# --- match_albums.py:7992
def hub_centre(g, cx, cy, r):
    """The centre of the rings round a disc's hub, and how far (a share of r) the strongest
    ring edge at each angle lies from a circle round it: (cx, cy, misfit). A close-up of a
    hub fits within a percent or two; a cover or a printed disc face does not."""
    import numpy as np
    a = np.asarray(g, dtype=np.float32)
    h, w = a.shape
    th = np.linspace(0, 2 * np.pi, 360, endpoint=False)
    M = np.c_[np.ones(len(th)), np.cos(th), np.sin(th)]
    misfit = 1.0
    for _ in range(3):
        R = np.linspace(r * 0.45, r, max(20, int(r * 0.55)))
        T, RR = np.meshgrid(th, R)
        X = np.clip(cx + RR * np.cos(T), 0, w - 1).astype(int)
        Y = np.clip(cy + RR * np.sin(T), 0, h - 1).astype(int)
        edge = R[np.abs(np.diff(a[Y, X], axis=0)).argmax(axis=0)]
        keep = np.ones(len(th), bool)
        for _k in range(3):
            sol = np.linalg.lstsq(M[keep], edge[keep], rcond=None)[0]
            res = np.abs(M @ sol - edge)
            keep = res < max(3.0, float(np.median(res[keep])) * 2.5)
        misfit = float(np.median(res)) / r
        if misfit > HUB_FIT:
            break
        cx, cy = cx + sol[1], cy + sol[2]
    return cx, cy, misfit


# --- match_albums.py:8020
def _hub_bands(strip):
    """The rows of a flat ring between two ring edges (rows whose median change down the
    strip is strong all the way round), 12-150 rows tall."""
    import numpy as np
    a = np.asarray(strip, dtype=np.float32)
    dy = np.convolve(np.median(np.abs(np.diff(a, axis=0)), axis=1), np.ones(3) / 3, "same")
    edge = dy > max(6.0, 0.15 * float(dy.max()))
    cuts = [0] + [i for i in range(1, len(edge)) if edge[i] != edge[i - 1]] + [len(edge)]
    return [(y0, y1) for y0, y1 in zip(cuts, cuts[1:]) if not edge[y0] and 12 <= y1 - y0 <= 150]


# --- match_albums.py:8031
def _otsu(a):
    import numpy as np
    hist, edges = np.histogram(a, bins=64)
    w = np.cumsum(hist).astype(float)
    mu = np.cumsum(hist * edges[:-1])
    w2 = w[-1] - w
    ok = (w > 0) & (w2 > 0)
    between = np.zeros_like(w)
    between[ok] = (mu[-1] * w[ok] / w[-1] - mu[ok]) ** 2 / (w[ok] * w2[ok])
    return float(edges[int(between.argmax()) + 1])


# --- match_albums.py:8043
def _mark_runs(mask, h):
    """Column spans of a band holding marks, joined across gaps under 2.5 band heights."""
    import numpy as np
    on = np.convolve(mask.mean(axis=0), np.ones(5) / 5, "same") > 0.07
    out, x0, last = [], None, 0
    for x in np.flatnonzero(on):
        if x0 is None:
            x0 = x
        elif x - last > 2.5 * h:
            out.append((x0, last + 1))
            x0 = x
        last = x
    if x0 is not None:
        out.append((x0, last + 1))
    return [(a, b) for a, b in out if 1.5 * h <= b - a <= 40 * h]


# --- match_albums.py:8060
def _letters_at(piece, light, height):
    """A run's grey pixels brought to letters `height` px tall (the median line of marks)."""
    import numpy as np
    from PIL import Image
    t = _otsu(piece)
    marks = piece > t if light else piece < t
    marks[marks.mean(axis=1) > 0.6] = False
    lines, cur = [], 0
    for on in list(marks.mean(axis=1) > 0.04) + [False]:
        if on:
            cur += 1
        elif cur:
            lines.append(cur)
            cur = 0
    lines = [n for n in lines if n >= 5]
    if not lines:
        return None
    f = height / float(np.median(lines))
    im = Image.fromarray(piece.astype("uint8")).resize(
        (max(1, int(piece.shape[1] * f)), max(8, int(piece.shape[0] * f))), Image.LANCZOS)
    return np.asarray(im, dtype=np.float32)


# --- match_albums.py:8083
def _hub_pieces(g, cx, cy, r):
    """The runs of marks round a hub close-up, each as black-on-white images ready to read:
    at each letter height, cut at Otsu's level and at one between it and the background
    (faint letters beside bright blocks: Heatwave's "OPTICAL" between grey bars)."""
    import numpy as np
    from PIL import Image, ImageFilter, ImageOps
    k = HUB_R / r
    g = g.resize((max(1, int(g.width * k)), max(1, int(g.height * k))), Image.LANCZOS)
    cx, cy, r = cx * k, cy * k, HUB_R
    cx, cy, misfit = hub_centre(g, cx, cy, r)
    if misfit > HUB_FIT:
        return []
    f0, f1 = HUB_BAND
    strip = unwrap_ring(g, cx, cy, r * f0, r * f1)
    if strip is None:
        return []
    out = []
    for y0, y1 in _hub_bands(strip):
        pad = max(3, (y1 - y0) // 6)
        band = strip.crop((0, max(0, y0 - pad), strip.width, min(strip.height, y1 + pad)))
        # the strip is as long as the outer edge: a band further in is drawn out, put right
        at = f1 - (f1 - f0) * ((y0 + y1) / 2) / strip.height
        band = band.resize((max(1, int(band.width * at / f1)), band.height), Image.LANCZOS)
        a = np.asarray(band, dtype=np.float32)
        mean = np.asarray(band.filter(ImageFilter.BoxBlur(max(4, int(band.height * 0.4)))), dtype=np.float32)
        d = max(12.0, float(np.percentile(np.abs(a - mean), 90)) * 0.6)
        h = y1 - y0
        for light, mask in ((True, a > mean + d), (False, a < mean - d)):
            mask[mask.mean(axis=1) > 0.25] = False          # a ring's edge, not letters
            for x0, x1 in _mark_runs(mask, h)[:8]:
                piece = a[:, max(0, x0 - h):min(a.shape[1], x1 + h)]
                for height in HUB_LETTERS:
                    p = _letters_at(piece, light, height)
                    if p is None:
                        continue
                    t = _otsu(p)
                    marks = p > t if light else p < t
                    bg = float(np.median(p[~marks])) if (~marks).any() else t
                    for cut in (t, (bg + t) / 2):
                        ink = p > cut if light else p < cut
                        ink[ink.mean(axis=1) > 0.6] = False
                        im = Image.fromarray(np.where(ink, 0, 255).astype("uint8")).filter(ImageFilter.MinFilter(3))
                        out.append(ImageOps.expand(im, 20, fill=255))
    return out


# --- match_albums.py:8129
HUB_SURE = 55.0                     # tesseract's mean confidence a run's reading needs


# --- match_albums.py:8132
def _read_stacked(images, deadline=None):
    """Each small image read the way it runs: all four ways of each (as it comes, upside
    down, mirrored, both) stacked on pages (12000 px tall at most: a taller page reads
    nothing), one tesseract run a page, not one an image; of each image's four readings the
    one tesseract is surest of, kept when its words average HUB_SURE or more. Returns
    [(text, confidence)] in the images' order."""
    from PIL import Image
    rows = []                                   # (image index, picture)
    for i, im in enumerate(images):
        rows += [(i, v) for v in (im, im.rotate(180), im.transpose(Image.FLIP_LEFT_RIGHT),
                                  im.transpose(Image.FLIP_TOP_BOTTOM))]
    pages, cur, tall = [], [], 0
    for row in rows:
        if cur and tall + row[1].height + 10 > 12000:
            pages.append(cur)
            cur, tall = [], 0
        cur.append(row)
        tall += row[1].height + 10
    if cur:
        pages.append(cur)

    def read(page_rows):
        canvas = Image.new("L", (max(v.width for _i, v in page_rows) + 40,
                                 sum(v.height + 10 for _i, v in page_rows) + 40), 255)
        spans, y = [], 20
        for k, (_i, v) in enumerate(page_rows):
            canvas.paste(v, (20, y))
            spans.append((y, y + v.height, k))
            y += v.height + 10
        tsv = _tess_or_tsv(canvas, deadline)
        words = {}                              # row on the page -> [(line key, left, word, conf)]
        for line in tsv.splitlines()[1:]:
            f = line.split("\t")
            if len(f) < 12 or not f[11].strip():
                continue
            try:
                top, height, conf = int(f[7]), int(f[9]), float(f[10])
            except ValueError:
                continue
            mid = top + height / 2
            row = next((k for y0, y1, k in spans if y0 - 5 <= mid <= y1 + 5), None)
            if row is not None:
                words.setdefault(row, []).append(((f[2], f[3], f[4]), int(f[6]), f[11], conf))
        out = []
        for k, (i, _v) in enumerate(page_rows):
            ws = words.get(k) or []
            text, lines = "", {}
            for key, left, w, _c in ws:
                lines.setdefault(key, []).append((left, w))
            text = "\n".join(" ".join(w for _l, w in sorted(v)) for _key, v in sorted(lines.items()))
            chars = sum(len(w) for _k, _l, w, _c in ws)
            conf = sum(c * len(w) for _k, _l, w, c in ws) / chars if chars else 0.0
            out.append((i, text, conf))
        return out
    best = {}
    for page_out in _pmap(read, pages):
        for i, text, conf in page_out:
            if sum(ch.isalnum() for ch in text) >= 4 and conf > best.get(i, ("", -1.0))[1]:
                best[i] = (text, conf)
    return [best[i] for i in sorted(best) if best[i][1] >= HUB_SURE]


# --- match_albums.py:8194
def _tess_or_tsv(img, deadline=None):
    if deadline is not None and time.time() >= deadline:
        return ""
    try:
        return _tess(img, 4, tsv=True, deadline=deadline)
    except Exception:
        return ""


# --- match_albums.py:8203
def ocr_hub_closeup(g, found, deadline=None):
    """The text round a hub close-up (OCR-7), or "" when the scan is not one."""
    try:
        pieces = _hub_pieces(g, *found)
        return "\n".join(text for text, _conf in _read_stacked(pieces, deadline)) if pieces else ""
    except Exception:
        return ""                           # (the scan's other readings are kept)


